// Pre-built series catalog. Generated by scripts/generate-series-index.mjs
// and committed to the repository so the plugin can skip crawling.
export const SERIES_INDEX_URL =
    "https://raw.githubusercontent.com/azbashar/nuvio-bdix/refs/heads/main/series_index.json";

// Top-level folders that hold TV shows on the different BDIX shares.
export const SERIES_ROOT_RE =
    /^(tv\s*shows?|web\s*series|webseries|series|shows?)$/i;

// Some shares keep cartoons/kids shows under Other(s)/<category>.
export const OTHER_ROOT_RE = /^others?$/i;
export const CARTOON_ROOT_RE = /cartoon|kids|animation|anime/i;

// A season folder looks like "<Show> Season 01 (2020) [tags]".
export const SEASON_FOLDER_RE =
    /^(.*?)\s+season\s+s?(\d{1,2})(?:\s*[-–]\s*s?\d{1,2})?\s*(?:\((\d{4})\))?(.*)$/i;

export const MAX_CRAWL_DEPTH = 7;
